type VirtualFoldersInitParameters struct {

	// Optional description.
	Description *string `json:"description,omitempty" tf:"description,omitempty"`

	// Exposes only the listed sub-paths of the folder: each entry is mounted as a virtual directory under the virtual path and serves the matching sub-path of the folder. Canonical POSIX paths with a leading slash, each exposing a distinct subtree. On group mappings the same placeholders as the subpath are supported. Mutually exclusive with `subpath`. Available in the Enterprise edition.
	ExposedSubpaths []*string `json:"exposedSubpaths,omitempty" tf:"exposed_subpaths,omitempty"`

	// Last quota update as unix timestamp in milliseconds
	LastQuotaUpdate *float64 `json:"lastQuotaUpdate,omitempty" tf:"last_quota_update,omitempty"`

	// Absolute path to a local directory. This is the folder root path for local storage provider. For non-local filesystems it will store temporary files.
	MappedPath *string `json:"mappedPath,omitempty" tf:"mapped_path,omitempty"`

	// Unique folder name
	Name *string `json:"name,omitempty" tf:"name,omitempty"`

	// Maximum number of files allowed. Not set means unlimited, -1 included in user quota
	QuotaFiles *float64 `json:"quotaFiles,omitempty" tf:"quota_files,omitempty"`

	// Maximum size allowed as bytes. Not set means unlimited, -1 included in user quota
	QuotaSize *float64 `json:"quotaSize,omitempty" tf:"quota_size,omitempty"`

	// Re-roots the mapping: the mount at the virtual path serves the folder starting from this sub-path, which stays invisible in the virtual tree. Canonical POSIX path with a leading slash (e.g. `/tenant1`). The same folder can be mapped multiple times with distinct subpaths; every mapping of the same folder must use the same quota limits. On group mappings the `%username%` and `%role%` placeholders are supported. Mutually exclusive with `exposed_subpaths`.
	Subpath *string `json:"subpath,omitempty" tf:"subpath,omitempty"`

	// Used quota as number of files.
	UsedQuotaFiles *float64 `json:"usedQuotaFiles,omitempty" tf:"used_quota_files,omitempty"`

	// Used quota as bytes.
	UsedQuotaSize *float64 `json:"usedQuotaSize,omitempty" tf:"used_quota_size,omitempty"`

	// The folder will be available on this path.
	VirtualPath *string `json:"virtualPath,omitempty" tf:"virtual_path,omitempty"`
}

